WITH "__duckstream_0" AS (SELECT CAST(COALESCE(SUM(t.c1), 0) AS BIGINT) AS c0, CAST(COUNT(t.c0) AS BIGINT) AS c1, CAST(MIN(t.c2) AS TIMESTAMP) AS c2, CAST(MAX(t.c3) AS TIMESTAMP) AS c3 FROM (SELECT t.c0 AS c0, CAST(COUNT(*) AS BIGINT) AS c1, CAST(MIN(t.c1) AS TIMESTAMP) AS c2, CAST(MAX(t.c2) AS TIMESTAMP) AS c3 FROM (SELECT "id" AS c0, "a" AS c1, "b" AS c2 FROM "instants") t GROUP BY t.c0) t)
SELECT CAST(result.c0 AS BIGINT) AS "hits", CAST(result.c1 AS BIGINT) AS "visitors", CAST(result.c2 AS TIMESTAMP) AS "first_epoch", CAST(result.c3 AS TIMESTAMP) AS "last_epoch" FROM (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2, v.c3 AS c3 FROM "__duckstream_0" v) result;
